def test_ghz_circuit_structure():
  qc = build_ghz_circuit(4)
  assert qc.num_qubits == 4
  names = [i.operation.name
           for i in qc.data]
  assert names == ["h","cx","cx","cx"]
  cx_ctrl = {i.qubits[0]._index
    for i in qc.data
    if i.operation.name=="cx"}
  assert cx_ctrl == {0}

@pytest.mark.parametrize(
  "n_qubits", [2, 3, 5, 8])
def test_ghz_structure_across_sizes(
    n_qubits):
  qc = build_ghz_circuit(n_qubits)
  assert qc.num_qubits == n_qubits
  cx = sum(1 for i in qc.data
    if i.operation.name=="cx")
  assert cx == n_qubits - 1
